<?php declare(strict_types=1); ?>
<div class="page-wrap financial-report"><a href="<?= pl_e(pl_url('/reports')) ?>" class="back-link"><?= pl_icon('arrow-left') ?> All reports</a><div class="page-heading"><div><p class="eyebrow">Plan the next few weeks</p><h1>Cash forecast</h1><p class="muted">A simple cash scenario for <?= pl_e($company['name']) ?>.</p></div><span class="badge sample">Planning scenario · Not actuals</span></div>
<?php if ($form['message']): ?><div class="alert" role="alert"><?= pl_e($form['message']) ?> Your assumptions remain below.</div><?php endif; ?>
<div class="forecast-layout"><form method="post" action="<?= pl_e(pl_url('/reports/cash-forecast')) ?>" class="panel forecast-assumptions"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><p class="eyebrow">Your assumptions</p><h2>What might change?</h2><p class="muted small">Starting cash is <?= pl_e($company['currency'] . ' ' . pl_money($opening)) ?> from posted cash/bank accounts through <?= pl_e(pl_date_label($asOf)) ?>.</p><div class="form-grid"><label class="field full-width">Expected money in each week<input type="text" inputmode="decimal" name="weekly_in" value="<?= pl_e($input['weekly_in']) ?>" required pattern="[0-9]+(\.[0-9]{1,4})?"></label><label class="field full-width">Expected money out each week<input type="text" inputmode="decimal" name="weekly_out" value="<?= pl_e($input['weekly_out']) ?>" required pattern="[0-9]+(\.[0-9]{1,4})?"></label><label class="field full-width">Number of weeks<input type="number" name="weeks" min="1" max="52" value="<?= pl_e($input['weeks']) ?>" required></label></div><button type="submit" class="button primary">Update scenario</button><p class="small muted">Use decimal points without separators. <?= $company['is_sample'] ? 'The starting assumptions are illustrative sample amounts.' : 'Enter your own assumptions; no automatic prediction is made.' ?> This does not post entries or change the books.</p></form>
<div><?php if ($forecast): ?><div class="forecast-outcome"><p class="eyebrow">After <?= (int) $forecast['weeks'] ?> weeks</p><h2><?= pl_e($company['currency'] . ' ' . pl_money($forecast['closing'])) ?></h2><p><?= $forecast['first_negative_week'] !== null ? 'This scenario first falls below zero in week ' . (int) $forecast['first_negative_week'] . '.' : 'Cash stays at or above zero under these assumptions.' ?></p></div><div class="forecast-chart"><canvas width="760" height="280" data-forecast-chart data-values="<?= pl_e(json_encode(array_merge([$forecast['opening']], array_column($forecast['rows'], 'closing')), JSON_THROW_ON_ERROR)) ?>" aria-label="Scenario cash balance by week. Exact amounts appear in the table below." role="img"></canvas></div><p class="small muted">Opening cash + assumed inflows − assumed outflows. No receivables timing, seasonality, taxes or unrecorded commitments are automatically included.</p><?php else: ?><div class="empty-state"><h2>Adjust the assumptions to continue.</h2><p>The scenario will appear here when the values are valid.</p></div><?php endif; ?></div></div>
<?php if ($forecast): ?><details class="forecast-table" open><summary>Week-by-week cash plan</summary><div class="table-wrap"><table class="data-table"><caption class="sr-only">Scenario amounts in <?= pl_e($company['currency']) ?></caption><thead><tr><th>Week</th><th class="amount">Opening</th><th class="amount">Money in</th><th class="amount">Money out</th><th class="amount">Closing</th></tr></thead><tbody><?php foreach ($forecast['rows'] as $row): ?><tr><th scope="row"><?= (int) $row['week'] ?></th><td class="amount"><?= pl_e(pl_money($row['opening'])) ?></td><td class="amount"><?= pl_e(pl_money($row['inflow'])) ?></td><td class="amount"><?= pl_e(pl_money($row['outflow'])) ?></td><td class="amount"><strong><?= pl_e(pl_money($row['closing'])) ?></strong></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?></div>
